const hc=lang=>houseContent[lang]||houseContent.pt;
const tr=lang=>dict[lang]||dict.pt;
const url=(p,lang)=>`${p}${lang==='en'?(p.includes('?')?'&':'?')+'lang=en':''}`;
const price=(p,s,lang)=>!s.showPrices||p.priceOnRequest?tr(lang).onrequest:new Intl.NumberFormat(lang==='pt'?'pt-BR':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(p.priceCents/100);
const title=(p,lang)=>lang==='pt'?p.namePt:p.name;
const status=(p,lang)=>tr(lang)[p.status]||p.status;
function brand(home,compact=false){return `<a class="brand${compact?' compact':''}" href="${home}" aria-label="Hillkings — Fine Gemstones"><img src="/brand/monogram.png" width="56" height="49" alt="" class="brand-monogram"><span class="brand-name">HILLKINGS<small>FINE GEMSTONES</small></span></a>`;}
function header(lang){const t=tr(lang),c=hc(lang);return `
<a class="skip-link" href="#main">${lang==='pt'?'Ir ao conteúdo':'Skip to content'}</a>
<header class="site-header"><div class="header-inner">
<nav class="nav-left" aria-label="${lang==='pt'?'Principal':'Main'}"><a href="${url('/collection',lang)}">${t.collection}</a><a href="${url('/',lang)}#house">${t.house}</a><a href="${url('/',lang)}#concierge">Concierge</a></nav>
${brand(url('/',lang))}
<div class="nav-right"><button class="language-button" data-language="${lang==='pt'?'en':'pt'}" aria-label="${lang==='pt'?'Switch to English':'Mudar para português'}">${lang.toUpperCase()} ${icon('down',12)}</button><a class="nav-contact-link" href="${url('/private',lang)}">${c.contact}</a><button class="nav-concierge" data-contact>${t.private} ${icon('diagonal',14)}</button><button class="mobile-menu-toggle icon-button" aria-label="${lang==='pt'?'Abrir menu':'Open menu'}" aria-expanded="false" aria-controls="mobileMenu">${icon('menu',25)}</button></div>
</div><nav id="mobileMenu" class="mobile-nav" hidden><a href="${url('/collection',lang)}">${t.collection}</a><a href="${url('/',lang)}#concierge">${c.concierge}</a><a href="${url('/',lang)}#house">${t.house}</a><a href="${url('/',lang)}#trade">${lang==='pt'?'Atacado & entregas':'Wholesale & delivery'}</a><a href="${url('/',lang)}#experience">${t.experience}</a><a href="${url('/private',lang)}">${c.contact}</a></nav></header>`;}
function footer(s,lang){const t=tr(lang),c=hc(lang);return `
<footer class="site-footer"><div class="footer-top">${brand(url('/',lang))}<p>${t.from}</p><a class="text-link" href="${url('/private',lang)}">${c.concierge} ${icon('diagonal',17)}</a></div>
<div class="footer-services"><span>${lang==='pt'?'Gemas sob encomenda · Compras no atacado · Entregas internacionais':'Gemstone sourcing · Wholesale purchasing · Worldwide delivery'}</span><nav aria-label="${lang==='pt'?'Serviços':'Services'}"><a href="${url('/',lang)}#house">${t.house}</a><a href="${url('/',lang)}#concierge">Concierge</a><a href="${url('/',lang)}#trade">${lang==='pt'?'Atacado':'Wholesale'}</a><a href="${url('/private',lang)}">${c.contact}</a></nav></div>
<div class="footer-bottom"><span>© ${new Date().getFullYear()} Hillkings. ${t.copyright}</span><span>${s.legalName?e(s.legalName):'HILLKINGS FINE GEMSTONES'}${s.taxId?' · '+e(s.taxId):''}</span><a href="${url('/privacy',lang)}">${t.privacy}</a></div></footer>
<a class="whatsapp-float" href="https://wa.me/${e(s.whatsapp)}?text=${encodeURIComponent(lang==='pt'?'Olá! Gostaria de falar com o concierge Hillkings.':'Hello. I would like to speak with the Hillkings concierge.')}" target="_blank" rel="noopener noreferrer" aria-label="${t.whatsapp}">${icon('whatsapp',24)}</a>`;}
function contactForm(catalog,lang,id='inquiryForm'){const t=tr(lang),c=hc(lang);return `
<form id="${id}" class="contact-form" data-contact-form>
<div class="form-row"><label>${t.name} *<input name="name" autocomplete="name" required minlength="2" maxlength="120" placeholder="${lang==='pt'?'Nome e sobrenome':'Full name'}"></label><label>${t.email} *<input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="${lang==='pt'?'seu@email.com':'you@email.com'}"></label></div>
<div class="form-row"><label>${t.phone}<input name="phone" type="tel" autocomplete="tel" maxlength="40" placeholder="+55"></label><label>${c.destinationLabel}<input name="destination" autocomplete="off" maxlength="160" placeholder="${lang==='pt'?'País e cidade':'Country and city'}"></label></div>
<label>${c.requestLabel}<select name="requestType">${Object.entries(c.types).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label>
<div class="company-field" data-company-field hidden><label>${c.companyLabel}<input name="company" autocomplete="organization" maxlength="160" placeholder="${lang==='pt'?'Nome da empresa':'Company name'}" disabled></label></div>
<label>${t.interest}<select name="productId"><option value="">${lang==='pt'?'Nenhuma / sob encomenda':'None / sourcing request'}</option>${catalog.products.map(p=>`<option value="${e(p.id)}">${e(title(p,lang))} · ${e(p.carats)} ct${p.status==='sold'?' · '+t.sold:''}</option>`).join('')}</select></label>
<label>${t.message} *<textarea name="message" rows="4" required minlength="10" maxlength="4000" placeholder="${lang==='pt'?'Descreva o que procura, suas preferências e o prazo desejado…':'Describe what you are looking for, your preferences and desired timing…'}" aria-describedby="${id}-hint"></textarea></label><p id="${id}-hint" class="contact-field-hint">${c.contactHint}</p>
<div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<label class="check-label"><input type="checkbox" name="consent" required><span>${t.consent} <a href="${url('/privacy',lang)}" target="_blank" rel="noopener">${t.privacy}</a></span></label>
<p class="form-message" role="status" aria-live="polite"></p><button class="button button-dark" type="submit">${t.submit} ${icon('diagonal')}</button><small class="form-disclaimer">${t.sendnote}</small></form>`;}
function dialogs(catalog,lang){const t=tr(lang);return `<dialog class="contact-dialog" id="contactDialog" aria-labelledby="contactTitle"><div class="dialog-top"><span class="eyebrow">${t.privatekicker}</span><button class="icon-button" data-close-dialog aria-label="${t.close}">${icon('close',24)}</button></div><h2 id="contactTitle">${t.contacttitle}</h2><p>${t.contactintro}</p>${contactForm(catalog,lang)}<div class="form-divider"><span>${t.or}</span></div><a class="button button-outline-dark contact-whatsapp" href="https://wa.me/${e(catalog.settings.whatsapp)}" target="_blank" rel="noopener">${icon('whatsapp')} ${t.whatsapp}</a></dialog><dialog class="model-dialog" id="modelDialog" aria-labelledby="modelDialogTitle"><div class="dialog-top"><span id="modelDialogTitle" class="eyebrow">HILLKINGS · ${t.experience}</span><button class="icon-button" data-close-dialog aria-label="${t.close}">${icon('close',26)}</button></div><div id="modelDialogContent"></div></dialog><dialog class="image-dialog" id="imageDialog"><button class="icon-button" data-close-dialog aria-label="${t.close}">${icon('close',26)}</button><img alt=""><p class="image-caption"></p></dialog>`;}
function mediaCaption(m,lang){return m?.kind==='editorial'?(lang==='pt'?'Apresentação editorial · imagem gerada por IA':'Editorial presentation · AI-generated image'):tr(lang).original;}
function editorialCover(p){return p.media?.find(m=>m.url===(p.heroImage||p.media[0]?.url))?.kind==='editorial';}
export function viewerMarkup(p,lang,{lazy=true,dialog=false}={}){const t=tr(lang);return `<div class="gem-viewer${dialog?' dialog-viewer':''}" data-viewer data-product="${e(p.id)}" data-model="${e(p.modelUrl)}" data-model-kind="${e(p.modelKind)}" data-lazy="${lazy}" aria-label="${t.experience}: ${e(title(p,lang))}"><div class="viewer-tag"><span class="live-dot"></span> ${p.modelKind==='cad'?'MODELO CAD':lang==='pt'?'REPRESENTAÇÃO 3D':'3D REPRESENTATION'} <span>· ${e(p.id)}</span></div><span class="viewer-optics">${lang==='pt'?'Refração · luz de estúdio':'Refraction · studio light'}</span><canvas tabindex="0" role="img" aria-label="${e(title(p,lang))}. ${t.rotation}"></canvas><div class="viewer-loading"><span class="loader-ring"></span><p>${t.loading}</p></div><p class="viewer-error" hidden></p><div class="viewer-side-controls"><button class="icon-button" data-viewer-action="zoom-in" aria-label="${lang==='pt'?'Aproximar':'Zoom in'}">${icon('plus')}</button><button class="icon-button" data-viewer-action="zoom-out" aria-label="${lang==='pt'?'Afastar':'Zoom out'}"><span class="minus-sign">−</span></button><button class="icon-button" data-viewer-action="reset" aria-label="${t.reset}">${icon('rotate')}</button><button class="icon-button" data-viewer-action="fullscreen" aria-label="${lang==='pt'?'Tela cheia':'Fullscreen'}">⛶</button></div><details class="viewer-tuning"><summary>${lang==='pt'?'Ajustar iluminação':'Adjust lighting'}</summary><div><label>${lang==='pt'?'Posição da luz':'Light position'}<input data-light-angle type="range" min="0" max="360" value="0" step="2"></label><label>${lang==='pt'?'Exposição':'Exposure'}<input data-exposure type="range" min="0.55" max="1.6" value="0.95" step="0.05"></label><small>${lang==='pt'?'Iluminação ilustrativa, não calibrada.':'Illustrative, uncalibrated lighting.'}</small></div></details><div class="viewer-controls"><button data-viewer-action="auto" class="viewer-control" aria-pressed="false">${icon('rotate',16)} <span>${t.auto}</span></button><button data-viewer-action="light" class="viewer-control"><span class="light-dot"></span><span>${t.studiolight}</span></button><button data-viewer-action="macro" class="viewer-control">${icon('zoom',16)} <span>Macro</span></button></div><div class="viewer-bottom"><span>${t.rotation}</span><small>${p.modelKind==='cad'?(lang==='pt'?'Modelo CAD. Materiais e iluminação são ilustrativos.':'CAD model. Materials and lighting are illustrative.'):t.modelnote}</small></div></div>`;}

function reportBadge(p,lang,{inline=false}={}){
 if(String(p.reportLab||'').toUpperCase()!=='GIA'||p.reportState==='not-provided')return '';
 const hasCopy=Boolean(p.reportUrl),checked=hasCopy&&p.reportState==='checked';
 const heading=lang==='pt'?'Relatório GIA':'GIA report';
 const sub=lang==='pt'?(checked?'Conferido pela Hillkings':hasCopy?'Cópia disponível':'Cópia a anexar'):(checked?'Checked by Hillkings':hasCopy?'Copy available':'Copy pending');
 const note=lang==='pt'?'Relatório gemológico associado ao material descrito. Consulte o dossiê para o número, a cópia e o escopo; não é certificação da joia inteira.':'Gemological report associated with the described material. Consult the dossier for its number, copy and scope; it is not certification of the entire jewel.';
 const attr=inline?'href="#reportDetails" data-report-open':`href="${url('/piece/'+p.slug,lang)}#reportDetails"`;
 return `<a class="gia-badge${inline?' gia-badge-product':''}" ${attr} title="${e(note)}" aria-label="${heading} — ${sub}. ${lang==='pt'?'Ver documentação':'View documentation'}">${icon('file',19)}<span><strong>${heading}</strong><small>${sub}</small></span>${icon('diagonal',12)}</a>`;
}
function serviceRibbon(lang){return `<div class="service-ribbon" aria-label="${lang==='pt'?'Serviços Hillkings':'Hillkings services'}">${(lang==='pt'?['Curadoria individual','Gemas sob encomenda','Condições para atacado','Entregas internacionais']:['Individual selection','Gemstone sourcing','Wholesale terms','Worldwide delivery']).map((x,i)=>`<a href="${url('/',lang)}#${i<2?'concierge':'trade'}"><span>0${i+1}</span>${x}${icon('diagonal',13)}</a>`).join('')}</div>`;}
function sourcingSection(lang){const c=hc(lang);return `<section class="sourcing-section section-pad" id="concierge"><div class="sourcing-heading"><div><p class="eyebrow">${c.servicesKicker}</p><h2>${c.servicesTitle}</h2></div><div><p>${c.servicesIntro}</p><button class="button button-light" data-contact data-inquiry-type="sourcing">${c.sourceCTA} ${icon('diagonal')}</button></div></div><div class="sourcing-steps">${c.steps.map(([title,copy],i)=>`<article><span class="step-number">0${i+1}</span><h3>${title}</h3><p>${copy}</p></article>`).join('')}</div><p class="sourcing-note">${c.servicesNote}</p></section>`;}
function tradeSection(lang){const c=hc(lang);return `<section class="trade-section section-pad" id="trade"><article class="trade-card wholesale-card"><div class="service-symbol">${icon('cube',32)}</div><p class="eyebrow dark-eyebrow">${c.wholesaleKicker}</p><h2>${c.wholesaleTitle}</h2><p>${c.wholesaleCopy}</p><small>${c.wholesaleNote}</small><button class="text-link" data-contact data-inquiry-type="wholesale">${c.wholesaleCTA} ${icon('diagonal',18)}</button></article><article class="trade-card world-card"><div class="service-symbol"><svg viewBox="0 0 32 32" width="32" height="32" fill="none" stroke="currentColor" stroke-width="1" aria-hidden="true"><circle cx="16" cy="16" r="12"/><ellipse cx="16" cy="16" rx="5.5" ry="12"/><path d="M4 16h24M6 9h20M6 23h20"/></svg></div><p class="eyebrow dark-eyebrow">${c.worldKicker}</p><h2>${c.worldTitle}</h2><p>${c.worldCopy}</p><small>${c.worldNote}</small><button class="text-link" data-contact data-inquiry-type="international">${c.worldCTA} ${icon('diagonal',18)}</button></article></section>`;}
function contactSection(catalog,lang){const c=hc(lang),t=tr(lang);return `<section class="contact-section section-pad" id="contact"><div class="contact-section-copy"><p class="eyebrow dark-eyebrow">${c.contactKicker}</p><h2>${c.contactTitle}</h2><p>${c.contactCopy}</p><a class="text-link" href="https://wa.me/${e(catalog.settings.whatsapp)}?text=${encodeURIComponent(lang==='pt'?'Olá! Gostaria de falar com o concierge Hillkings.':'Hello. I would like to speak with the Hillkings concierge.')}" target="_blank" rel="noopener">${icon('whatsapp',21)} ${t.whatsapp} ${icon('diagonal',16)}</a><div class="contact-monogram"><img src="/brand/monogram.png" width="96" height="83" alt=""><span>HILLKINGS<br>PRIVATE CONCIERGE</span></div></div><div class="contact-section-form"><h3>${c.formHeading}</h3><p class="contact-form-intro">${c.formNote}</p>${contactForm(catalog,lang,'homeInquiryForm')}</div></section>`;}
function faqSection(lang){const c=hc(lang);return `<section class="faq-section section-pad" id="faq"><div><p class="eyebrow dark-eyebrow">${c.faqKicker}</p><h2>${c.faqTitle}</h2></div><div class="faq-items">${c.faq.map(([q,a])=>`<details><summary>${q}${icon('plus',17)}</summary><p>${a}</p></details>`).join('')}</div></section>`;}

function card(p,s,lang){const t=tr(lang);const isRuby=p.heroImage?.includes('cutout'),isEditorial=editorialCover(p);return `<article class="product-card" data-category="${p.category}" data-status="${p.status}" data-search="${e((p.name+' '+p.namePt+' '+p.stone).toLowerCase())}"><a class="card-image${isRuby?' cutout-card':''}${isEditorial?' editorial-card':''}" href="${url('/piece/'+p.slug,lang)}" aria-label="${e(title(p,lang))}"><span class="card-ref">${e(p.id)}</span>${p.status!=='available'?`<span class="status-pill ${p.status}">${t[p.status]}</span>`:''}<img src="${e(isRuby?p.heroImage:p.media.find(m=>m.type==='image')?.url||p.heroImage)}" alt="${e(title(p,lang))}" loading="lazy" width="480" height="600">${isEditorial?`<span class="editorial-badge">${lang==='pt'?'APRESENTAÇÃO EDITORIAL · IA':'EDITORIAL PRESENTATION · AI'}</span>`:''}<span class="card-explore">${t.explore} ${icon('diagonal')}</span></a><div class="card-copy"><div class="card-assurance"><span class="eyebrow">${e(p.stone)} · ${e(p.carats)} CT</span>${reportBadge(p,lang)}</div><a href="${url('/piece/'+p.slug,lang)}"><h3>${e(title(p,lang))}</h3></a><div class="card-bottom"><span>${price(p,s,lang)}</span>${p.modelUrl?`<a class="card-3d-link" href="${url('/piece/'+p.slug,lang)}${lang==='en'?'&':'?'}view=3d">${icon('cube',16)} 3D</a>`:`<span>${p.reportLab?'GIA*':''}</span>`}</div></div></article>`;}
function conciergeBanner(lang){const t=tr(lang);return `<section class="concierge-banner"><div><p class="eyebrow">${t.privatekicker}</p><h2>${t.contactcta.replace('\n','<br>')}</h2></div><div><p>${lang==='pt'?'Algumas escolhas merecem uma conversa, não um carrinho de compras.':'Some choices deserve a conversation, not a shopping cart.'}</p><button class="button button-light" data-contact>${t.talk} ${icon('diagonal')}</button></div></section>`;}
function home(catalog,lang){const t=tr(lang),s=catalog.settings;const featured=catalog.products.find(p=>p.id===s.featuredProductId)||catalog.products[0];if(!featured)return `<section class="empty-collection"><p class="eyebrow">HILLKINGS FINE GEMSTONES</p><h1>${lang==='pt'?'Uma nova seleção está a caminho.':'A new selection is on its way.'}</h1><button class="button" data-contact>${t.private}</button></section>`;const model=catalog.products.find(p=>p.modelUrl);const selected=catalog.products.filter(p=>p.featured).slice(0,6);return `<section class="hero"><div class="hero-topline"><span>${t.inaugural}</span><span>PRIVATE CONCIERGE <span class="tiny-line"></span> WORLDWIDE</span></div><div class="hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="small-rule"></span> ${t.selected}</p><h1>${e(lang==='pt'?s.headline:s.headlineEn).replace(lang==='pt'?'extraordinário':'extraordinary',`<em>${lang==='pt'?'extraordinário':'extraordinary'}</em>`)}</h1><p class="hero-description">${e(lang==='pt'?s.intro:s.introEn)}</p><a href="${url('/collection',lang)}" class="button button-light">${t.discover} ${icon('diagonal')}</a><div class="hero-bottom-note"><span class="tiny-star">✧</span> ${t.byappointment}</div></div><div class="hero-piece"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="hero-piece-index">01 <i>/ ${String(catalog.products.length).padStart(2,'0')}</i></span><a class="hero-piece-photo" href="${url('/piece/'+featured.slug,lang)}"><img src="${e(featured.heroImage||featured.media[0]?.url)}" alt="${e(title(featured,lang))} — ${e(featured.carats)} ct" width="600" height="636" fetchpriority="high"></a>${featured.modelUrl?`<button class="hero-3d" data-model-open="${e(featured.id)}">${icon('cube',17)} ${t.view3d} ${icon('diagonal',14)}</button>`:''}<div class="hero-piece-label"><div><span class="eyebrow">${e(featured.name.toUpperCase())}</span><p>${e(featured.carats)} <span>CT</span><i>${e(featured.secondary||featured.cut)}</i></p></div><a href="${url('/piece/'+featured.slug,lang)}" class="circle-link" aria-label="${t.explore}">${icon('diagonal',25)}</a></div><span class="actual-note">${editorialCover(featured)?mediaCaption({kind:'editorial'},lang):t.original}</span></div></div><div class="hero-bottom"><span>${t.scroll} ↓</span><span>${t.scope} <b>·</b> ${t.service}</span></div></section>${serviceRibbon(lang)}<section class="collection-section section-pad" id="collection"><div class="section-heading"><div><p class="eyebrow dark-eyebrow">01 / ${t.pieces}</p><h2>${lang==='pt'?'Peças que não passam<br><em>despercebidas.</em>':'Pieces that never<br>go <em>unnoticed.</em>'}</h2></div><div class="section-heading-aside"><p>${lang==='pt'?'Uma seleção para ser observada com tempo. Descubra cada peça, suas particularidades e a documentação disponível.':'A selection to explore at your own pace. Discover every piece, its individual details and the available documentation.'}</p><a class="text-link" href="${url('/collection',lang)}">${t.all} ${icon('diagonal',17)}</a></div></div><div class="product-grid">${(selected.length?selected:catalog.products).map(p=>card(p,s,lang)).join('')}</div><p class="collection-footnote">* ${lang==='pt'?'A situação e o escopo dos relatórios GIA estão descritos na página de cada peça.':'The status and scope of GIA reports are described on each piece’s page.'}</p></section>${model?`<section class="experience-section section-pad" id="experience"><div class="experience-copy"><p class="eyebrow">02 / ${t.experience}</p><h2>${lang==='pt'?'Não apenas olhar.<br><em>Explorar.</em>':'More than a look.<br><em>A discovery.</em>'}</h2><p>${lang==='pt'?'Gire a montagem, aproxime os detalhes e descubra uma nova perspectiva do anel de rubi. Depois, compare com as imagens da peça real.':'Rotate the setting, move closer to the details and discover a new perspective on the ruby ring. Then compare it with images of the actual piece.'}</p><div class="experience-specs"><div><strong>${e(model.carats)}</strong><span>CT · ${e(model.stone).toUpperCase()}</span></div><div><strong>360°</strong><span>${lang==='pt'?'EXPLORAÇÃO INTERATIVA':'INTERACTIVE EXPLORATION'}</span></div></div><a class="text-link light-link" href="${url('/piece/'+model.slug+'?view=3d',lang)}">${t.explore} ${icon('diagonal',17)}</a></div><div class="experience-stage">${viewerMarkup(model,lang)}</div></section>`:''}<section class="house-section section-pad" id="house"><div class="house-art"><div class="house-art-frame"><img src="/brand/monogram.png" alt="Monograma Hillkings" width="220" height="190"><span>${hc(lang).legacyKicker}</span><p>${lang==='pt'?'JOIAS QUE FICAM.<br>HISTÓRIAS QUE SEGUEM.':'JEWELS THAT ENDURE.<br>STORIES THAT CONTINUE.'}</p></div><span class="house-art-caption">HILLKINGS · FINE GEMSTONES</span></div><div class="house-copy"><p class="eyebrow dark-eyebrow">03 / ${t.house}</p><h2>${t.househeading.replace('\n','<br>')}</h2><p>${t.housecopy}</p><p>${hc(lang).legacySecond}</p><blockquote class="legacy-quote">${hc(lang).legacyQuote}</blockquote><div class="house-principles"><div><span>01</span><p>${lang==='pt'?'Um olhar individual para cada peça.':'An individual eye for every piece.'}</p></div><div><span>02</span><p>${lang==='pt'?'Imagens reais. Informação com clareza.':'Real images. Clear information.'}</p></div><div><span>03</span><p>${lang==='pt'?'Uma relação que começa na conversa.':'A relationship that starts with a conversation.'}</p></div></div></div></section>${sourcingSection(lang)}${tradeSection(lang)}${contactSection(catalog,lang)}${faqSection(lang)}`;}
function collection(catalog,lang){const t=tr(lang),s=catalog.settings;return `<section class="catalog-header section-pad"><a class="breadcrumb" href="${url('/',lang)}">HILLKINGS <span>/ ${t.collection}</span></a><div class="catalog-heading"><div><p class="eyebrow">${t.selected}</p><h1>${lang==='pt'?'Uma coleção.<br><em>Muitas histórias.</em>':'One collection.<br><em>Many stories.</em>'}</h1></div><p>${lang==='pt'?'Gemas soltas e joias prontas para uma apresentação individual. Cada peça, uma descoberta.':'Loose gemstones and fine jewellery, ready for a personal presentation. Every piece, a discovery.'}</p></div></section><section class="catalog-body section-pad"><div class="catalog-toolbar"><div class="filters" role="group" aria-label="${lang==='pt'?'Filtrar coleção':'Filter collection'}"><button class="active" data-filter="all">${t.all}<sup>${catalog.products.length}</sup></button><button data-filter="gemstones">${t.gems}</button><button data-filter="jewellery">${t.jewels}</button><button data-filter="sold">${t.archived}</button></div><input class="catalog-search" type="search" placeholder="${lang==='pt'?'Buscar uma peça':'Find a piece'}" aria-label="${lang==='pt'?'Buscar uma peça':'Find a piece'}"></div><div class="product-grid">${catalog.products.map(p=>card(p,s,lang)).join('')}</div><p class="empty-filter" hidden>${t.filterempty}</p><p class="collection-footnote">* ${lang==='pt'?'Consulte a situação dos relatórios e as informações de cada produto.':'Refer to each product for report status and details.'} ${t.offernote}</p></section>${conciergeBanner(lang)}`;}
function product(p,catalog,lang){const t=tr(lang),s=catalog.settings;const first=p.media.find(m=>m.type==='image'),vid=p.media.find(m=>m.type==='video');const params=url('/collection',lang);return `<section class="product-page section-pad"><a class="breadcrumb" href="${params}">← ${t.back}</a><div class="product-layout"><div class="product-visual"><div class="product-tabs" role="tablist" aria-label="${t.gallery}"><button role="tab" class="active" aria-selected="true" data-product-tab="photo" id="tab-photo" aria-controls="panel-photo">${t.gallery}</button>${vid?`<button role="tab" aria-selected="false" data-product-tab="video" id="tab-video" aria-controls="panel-video">${t.video}</button>`:''}${p.modelUrl?`<button role="tab" aria-selected="false" data-product-tab="model" id="tab-model" aria-controls="panel-model">${icon('cube',15)} 3D</button>`:''}</div><div class="product-media-panel active" id="panel-photo" role="tabpanel" aria-labelledby="tab-photo"><button class="primary-photo" data-zoom-image="${e(first?.url||p.heroImage)}" aria-label="${lang==='pt'?'Ampliar fotografia':'Enlarge photograph'}"><img id="productMainImage" src="${e(first?.url||p.heroImage)}" alt="${e(first?.alt||title(p,lang))}" width="720" height="850"><span>${icon('zoom',20)}</span></button><div class="thumbnails">${p.media.filter(m=>m.type==='image').map((m,i)=>`<button data-thumbnail="${e(m.url)}" data-media-kind="${m.kind==='editorial'?'editorial':'original'}" class="${i===0?'active':''}" aria-label="${e(m.alt||title(p,lang))}"><img src="${e(m.url)}" alt="" loading="lazy"></button>`).join('')}<span data-photo-caption>${mediaCaption(first,lang)}</span></div><p class="editorial-disclosure" data-editorial-disclosure ${first?.kind==='editorial'?'':'hidden'}>${lang==='pt'?'Imagem gerada por IA para apresentação visual. Cor, lapidação, inclusões, montagem e proporções podem divergir da peça real. Consulte as fotos e o vídeo originais.':'AI-generated editorial image. Colour, cut, inclusions, setting and proportions may differ from the actual piece. Refer to the original photographs and footage.'}</p></div>${vid?`<div class="product-media-panel" id="panel-video" role="tabpanel" aria-labelledby="tab-video" hidden><video controls playsinline preload="none" poster="${e(vid.poster||first?.url||'')}" src="${e(vid.url)}" aria-label="${t.video}"></video><span class="video-authentic-note">${t.video} · HILLKINGS</span></div>`:''}${p.modelUrl?`<div class="product-media-panel" id="panel-model" role="tabpanel" aria-labelledby="tab-model" hidden>${viewerMarkup(p,lang)}<p class="model-description">${e(p.modelNotes)}</p></div>`:''}</div><div class="product-info"><div class="product-info-top"><span class="eyebrow">${e(p.id)} · HILLKINGS</span><span class="availability ${p.status}"><i></i>${status(p,lang)}</span></div><h1>${e(title(p,lang))}</h1><p class="product-spec-line">${e(p.carats)} ct · ${e(p.stone)}</p>${reportBadge(p,lang,{inline:true})}<p class="product-description">${e(lang==='en'?(p.descriptionEn||p.description):p.description)}</p><div class="product-price"><span>${t.price}</span><strong>${price(p,s,lang)}</strong></div><button class="button button-light full-width" data-contact="${e(p.id)}">${p.status==='sold'?t.similar:t.request} ${icon('diagonal')}</button><a class="product-whatsapp text-link light-link" href="https://wa.me/${e(s.whatsapp)}?text=${encodeURIComponent((lang==='pt'?'Olá! Gostaria de informações sobre ':'Hello. I would like information about ')+p.name+' ('+p.id+').')}" target="_blank" rel="noopener">${icon('whatsapp',18)} ${t.whatsapp}</a><div class="product-accordions"><details open><summary>${t.details}${icon('plus',16)}</summary><dl class="spec-table">${[[t.weight,`${p.stone} · ${p.carats} ct`],[t.diamonds,p.secondary],[t.metal,p.metal],[t.cut,p.cut],[t.origin,p.origin],[t.dimensions,p.dimensions],[t.treatments,p.treatment]].filter(([,v])=>v).map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></details><details id="reportDetails"><summary>${t.report}${icon('plus',16)}</summary><div class="report-content"><span class="report-status">${e(p.reportLab||'GIA')} · ${p.reportState==='checked'?t.checked:p.reportUrl?t.provided:t.reportpending}</span>${p.reportNumber?`<p class="report-number">Nº ${e(p.reportNumber)}</p>`:''}<p>${e(p.reportNotes)}</p>${p.reportUrl?`<a class="text-link light-link" href="${e(p.reportUrl)}" target="_blank" rel="noopener">${icon('file',17)} ${t.viewreport} ${icon('diagonal',14)}</a>`:''}${p.reportNumber&&p.reportLab==='GIA'?`<a class="text-link light-link" href="https://www.gia.edu/report-check?reportno=${encodeURIComponent(p.reportNumber)}" target="_blank" rel="noopener noreferrer">${t.checkgia} ${icon('diagonal',14)}</a>`:''}<small>${t.reportdisclaimer}</small></div></details></div><p class="offer-note">${t.offernote}</p></div></div></section><section class="documentation-section section-pad"><span class="eyebrow dark-eyebrow">${t.documentation}</span><h2>${t.reporttitle}</h2><p>${t.reportcopy}</p></section>`;}
function privatePage(catalog,lang){const t=tr(lang),c=hc(lang);return `<section class="private-page section-pad"><div class="private-copy"><p class="eyebrow">${c.servicesKicker}</p><h1>${t.contacttitle}</h1><p>${c.contactCopy}</p><div class="private-service-list"><span>${lang==='pt'?'Apresentações individuais':'Private presentations'}</span><span>${lang==='pt'?'Gemas sob encomenda':'Gemstones sourced to order'}</span><span>${lang==='pt'?'Atacado & entregas internacionais':'Wholesale & international delivery'}</span></div><a class="button button-outline" href="https://wa.me/${e(catalog.settings.whatsapp)}" target="_blank" rel="noopener">${icon('whatsapp')} ${t.whatsapp}</a><span class="private-mark"><img src="/brand/monogram.png" alt="" width="140" height="120"></span><small>${t.byappointment}</small></div><div class="private-form-panel"><h2>${c.formHeading}</h2><p class="contact-form-intro">${c.formNote}</p>${contactForm(catalog,lang,'privateInquiryForm')}</div></section>${faqSection(lang)}`;}
function privacy(catalog,lang){const t=tr(lang),s=catalog.settings;return `<section class="privacy-page section-pad"><p class="eyebrow">HILLKINGS</p><h1>${t.privacy}</h1><p>${t.retention}</p><h2>${lang==='pt'?'O que é registrado':'What is recorded'}</h2><p>${lang==='pt'?'Ao enviar o formulário, você informa nome, e-mail, telefone opcional, tipo de atendimento, destino e empresa opcionais, peça de interesse e mensagem. A solicitação fica disponível apenas na administração autenticada e pode ser encaminhada ao e-mail do atendimento por um provedor de envio.':'When submitting the form, you provide your name, email, optional telephone number, enquiry type, optional destination and company, piece of interest and message. Your enquiry is available only to authenticated administrators and may be forwarded to the concierge email through an email delivery provider.'}</p><h2>${lang==='pt'?'Contato e exclusão':'Contact and deletion'}</h2><p>${lang==='pt'?'Para solicitar acesso, correção ou exclusão das suas informações, entre em contato com a Hillkings pelo WhatsApp indicado abaixo.':'To request access, correction or deletion of your information, contact Hillkings using the WhatsApp link below.'}</p><a class="text-link light-link" href="https://wa.me/${e(s.whatsapp)}" target="_blank" rel="noopener">${t.whatsapp} ${icon('diagonal')}</a><h2>${lang==='pt'?'Serviços externos':'External services'}</h2><p>${lang==='pt'?'Os links para WhatsApp e GIA abrem serviços externos, sujeitos às políticas dos respectivos operadores. Não há analytics publicitário nem pixel de anúncios instalado nesta versão. A administração utiliza um cookie de sessão necessário para autenticação.':'WhatsApp and GIA links open external services subject to their operators’ policies. This version contains no advertising analytics or advertising pixels. Administration uses a session cookie required for authentication.'}</p>${s.legalName?`<h2>${lang==='pt'?'Responsável':'Operator'}</h2><p>${e(s.legalName)}${s.taxId?' · '+e(s.taxId):''}<br>${e(s.address)}</p>`:''}<p class="privacy-updated">${lang==='pt'?'Versão inicial · setembro de 2026':'Initial version · September 2026'}</p></section>`;}
function admin(){return `<div id="adminApp" class="admin-app"><div class="admin-login-wrap"><a href="/" class="admin-back">← Voltar ao site</a><div class="admin-login-card">${brand('/')}<p class="eyebrow dark-eyebrow">PRIVATE OFFICE</p><h1>Administração</h1><p>Acesso reservado à gestão da Hillkings.</p><form id="loginForm"><label>Usuário<input name="username" autocomplete="username" value="admin" required maxlength="40"></label><label>Senha<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><p class="form-message" role="status"></p><button class="button button-dark" type="submit">Entrar ${icon('arrow')}</button></form><small>${icon('lock',14)} Sessão autenticada · acesso restrito</small></div></div></div><dialog id="adminEditor" class="admin-editor"></dialog><div id="adminToast" class="admin-toast" role="status" aria-live="polite" hidden></div>`;}
export function renderPage(pathname,catalog,lang,appUrl){
 const t=tr(lang);let content='',statusCode=200;let page='home',metaTitle=catalog.settings.siteTitle,description=catalog.settings.description;
 if(pathname==='/')content=home(catalog,lang);
 else if(pathname==='/collection'){page='collection';content=collection(catalog,lang);metaTitle=`${t.collection} — Hillkings`;}
 else if(pathname.startsWith('/piece/')){const p=catalog.products.find(p=>p.slug===pathname.slice(7));if(p){page='product';content=product(p,catalog,lang);metaTitle=`${title(p,lang)} · ${p.carats} ct — Hillkings`;description=lang==='en'?p.descriptionEn:p.description;}else statusCode=404;}
 else if(pathname==='/private'||pathname==='/contact'||pathname==='/concierge'){page='private';content=privatePage(catalog,lang);metaTitle=`${t.private} — Hillkings`;}
 else if(pathname==='/privacy'){page='privacy';content=privacy(catalog,lang);metaTitle=`${t.privacy} — Hillkings`;}
 else if(pathname==='/admin'){page='admin';content=admin();metaTitle='Private Office — Hillkings';}
 else statusCode=404;
 if(statusCode===404){page='notfound';content=`<section class="notfound section-pad"><span class="eyebrow">HILLKINGS / 404</span><h1>${t.noresult}</h1><p>${t.notfoundcopy}</p><a class="button button-light" href="${url('/collection',lang)}">${t.collection} ${icon('arrow')}</a></section>`;}
 const mainProduct=catalog.products.find(p=>p.slug===pathname.slice(7));
 const bootstrap=page==='admin'?{page,lang}:{...catalog,page,lang,productId:mainProduct?.id||null};
 const html=`<!doctype html><html lang="${lang==='pt'?'pt-BR':'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(metaTitle)}</title><meta name="description" content="${e(description)}"><meta name="theme-color" content="#08231d"><meta name="color-scheme" content="dark light"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="/icons/favicon-32.png"><link rel="icon" type="image/png" sizes="64x64" href="/icons/favicon-64.png"><link rel="apple-touch-icon" sizes="180x180" href="/icons/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><link rel="canonical" href="${e(appUrl+url(pathname,lang))}"><meta property="og:type" content="website"><meta property="og:title" content="${e(metaTitle)}"><meta property="og:description" content="${e(description)}"><meta property="og:image" content="${e(appUrl+(mainProduct?.media?.find(m=>m.type==='image')?.url||'/brand/identity.webp'))}">${page==='admin'?'<meta name="robots" content="noindex,nofollow">':''}<link rel="stylesheet" href="/assets/main.css">${page==='admin'?'<link rel="stylesheet" href="/assets/admin.css">':''}</head><body class="page-${page}">${page!=='admin'?header(lang):''}<main id="main">${content}</main>${page!=='admin'?footer(catalog.settings,lang)+dialogs(catalog,lang)+catalog.products.filter(p=>p.modelUrl).map(p=>`<template id="viewerTemplate-${e(p.id)}">${viewerMarkup(p,lang,{lazy:false,dialog:true})}</template>`).join(''):''}<script type="application/json" id="bootstrap">${jsonForHtml(bootstrap)}</script><script type="module" src="/assets/${page==='admin'?'admin':'app'}.js"></script></body></html>`;
 return {html,status:statusCode};
}
